// App.jsx
import React from "react";

const projectData = {
  title: "Système de Gestion de Points de Vente (POS)",
  role: "Développeur Full-Stack",
  techStack: [
    "React.js",
    "Node.js + Express",
    "MySQL",
    "JWT",
    "Chart.js",
    "PDFKit",
    "ExcelJS",
  ],
  description:
    "Application web complète de gestion multi-magasins avec gestion des utilisateurs, produits, ventes, tableaux de bord et exports PDF/Excel.",
  features: [
    "Gestion multi-utilisateurs avec rôles",
    "Gestion multi-points de vente",
    "Interface caissier simplifiée",
    "Dashboard analytique",
    "Export PDF/Excel des rapports",
  ],
  githubLink: "https://github.com/tonrepo",
  demoLink: "https://tonapp.vercel.app",
};

function ProjectCard({ project }) {
  return (
    <div className="project-card" style={styles.card}>
      <h2>{project.title}</h2>
      <p><strong>Rôle :</strong> {project.role}</p>
      <p><strong>Technologies :</strong> {project.techStack.join(", ")}</p>
      <p>{project.description}</p>
      <h3>Fonctionnalités :</h3>
      <ul>
        {project.features.map((f, i) => (
          <li key={i}>{f}</li>
        ))}
      </ul>
      <p>
        <a href={project.githubLink} target="_blank" rel="noreferrer">Code source GitHub</a> |{" "}
        <a href={project.demoLink} target="_blank" rel="noreferrer">Voir la démo</a>
      </p>
    </div>
  );
}

function App() {
  return (
    <div style={styles.container}>
      <header style={styles.header}>
        <h1>Aziz Ben Mohamed</h1>
        <p>Développeur Full-Stack | Data Analyst</p>
      </header>

      <section style={styles.section}>
        <h2>Projet Principal</h2>
        <ProjectCard project={projectData} />
      </section>

      <footer style={styles.footer}>
        <p>Contact : <a href="mailto:aziz@example.com">aziz@example.com</a></p>
        <p>
          <a href="https://github.com/tonrepo" target="_blank" rel="noreferrer">GitHub</a> |{" "}
          <a href="https://linkedin.com/in/tonprofil" target="_blank" rel="noreferrer">LinkedIn</a>
        </p>
      </footer>
    </div>
  );
}

const styles = {
  container: {
    fontFamily: "'Segoe UI', Tahoma, Geneva, Verdana, sans-serif",
    maxWidth: 800,
    margin: "auto",
    padding: 20,
    lineHeight: 1.6,
    color: "#333",
  },
  header: {
    textAlign: "center",
    marginBottom: 40,
  },
  section: {
    marginBottom: 40,
  },
  card: {
    border: "1px solid #ddd",
    borderRadius: 8,
    padding: 20,
    backgroundColor: "#fafafa",
  },
  footer: {
    textAlign: "center",
    borderTop: "1px solid #ddd",
    paddingTop: 15,
    fontSize: 14,
    color: "#666",
  },
};

export default App;
